import {adoptSuggestion,setPlanOwner,getActivePlan} from './active-plan.js';
import {validateProfile,validateSuggestion,localToday,addDate} from './training-contract.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let account=null,authChecked=false,status='',busy=false,checking=false,result=null,draft=null;
const labels=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const changed=()=>window.dispatchEvent(new Event('profile-change'));
function key(){return account?'dez-voltas-profile-v1:'+account.id:null;}
function defaults(){return {goal:'backyard',target:10,startDate:localToday(),targetDate:'2027-04-10'>localToday()?'2027-04-10':addDate(localToday(),180),weeklyKm:10,longestKm:21.1,weeksConsistent:0,days:[0,2,3,5],maxMinutes:60,longMinutes:120,pain:'none',consent:false};}
function load(){result=null;draft=null;try{const saved=JSON.parse(localStorage.getItem(key())||'null')||getActivePlan();if(saved){draft=saved.profile;const p=validateProfile(saved.profile,saved.profile.startDate);result={...saved,profile:p,plan:validateSuggestion(saved.plan,p)};}}catch{status='Não foi possível restaurar a sugestão salva. Gere outra ou importe um backup válido.';}}
async function api(path,body){let r;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),70000);try{r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',signal:controller.signal,headers:body===undefined?{}:{'content-type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});}catch(error){throw new Error(error.name==='AbortError'?'A solicitação demorou mais de um minuto. Tente novamente. Seu plano anterior foi preservado.':'Sem conexão. Tente novamente online. As cópias salvas não foram removidas.');}finally{clearTimeout(timeout);}if(!r.headers.get('content-type')?.includes('application/json'))throw new Error('Esta versão ainda precisa do servidor configurado no Cloudflare.');const data=await r.json();if(!r.ok){if(r.status===401){account=null;result=null;}throw new Error(data.error||'Não foi possível concluir.');}return data;}
function field(name,label,value,type='number',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${extra}></label>`;}
export function renderProfile(){const p=draft||defaults();return `<div class="page-heading"><div><span class="eyebrow">UM PLANO PARA O SEU OBJETIVO</span><h1>Seu próximo <em>desafio.</em></h1></div><a class="secondary" href="#plano">Ver plano atual</a></div>
<section class="panel profile-account"><h2>Sua conta</h2>${account?`<p>Conectado como <strong>${esc(account.email)}</strong></p><button class="secondary" data-profile="logout" ${busy?'disabled':''}>Sair da conta</button><p class="field-help">Conta confirmada. Perfil e sugestões ficam neste navegador até ativarmos a sincronização com o banco.</p>`:`<p>Entre com sua conta Google para acompanhar seu objetivo.</p><button type="button" class="primary google-login" data-profile="google" ${busy?'disabled':''}>Entrar com Google</button><details class="profile-email"><summary>Entrar com link por e-mail</summary><form id="profile-login" class="profile-login">${field('email','Seu e-mail','','email','autocomplete="email" maxlength="254"')}<button class="primary" ${busy?'disabled':''}>${busy?'Aguarde…':'Receber link de acesso'}</button></form><p class="field-help">Abra o link no mesmo navegador em que pediu. No iPhone, o Safari e o app instalado podem ter sessões separadas. ${authChecked?'':'Conferindo acesso…'}</p></details>`}<p id="profile-status" class="notice" role="status" aria-live="polite" ${status&&!account?'':'hidden'}>${esc(status)}</p></section>
<section class="panel profile-form-panel"><span class="eyebrow muted">PONTO DE PARTIDA</span><h2>Conte como você está hoje.</h2><p class="muted">A base das últimas quatro semanas orienta a sugestão. Um volume alto no passado não substitui a adaptação atual.</p><form id="profile-goal"><div class="profile-grid"><label class="field">Seu objetivo<select name="goal">${[['backyard','Completar voltas em backyard'],['distance','Completar uma distância (km)'],['time','Correr por um tempo (min)']].map(([v,t])=>`<option value="${v}" ${p.goal===v?'selected':''}>${t}</option>`).join('')}</select></label>${field('target','Meta: voltas, km ou minutos',p.target,'number','min="1" max="1440" step="0.1"')}${field('startDate','Início da preparação',p.startDate,'date')}${field('targetDate','Data do objetivo',p.targetDate,'date')}${field('weeklyKm','Média semanal nas últimas 4 semanas (km)',p.weeklyKm,'number','min="0" max="200" step="0.1"')}${field('longestKm','Maior treino nas últimas 4 semanas (km)',p.longestKm,'number','min="0" max="150" step="0.1"')}${field('weeksConsistent','Semanas seguidas treinando atualmente',p.weeksConsistent,'number','min="0" max="520" step="1"')}${field('maxMinutes','Tempo por treino comum (min)',p.maxMinutes,'number','min="20" max="360"')}${field('longMinutes','Tempo disponível para o longo (min)',p.longMinutes,'number','min="30" max="600"')}<label class="field">Dor ou retorno de lesão<select name="pain">${[['none','Sem dor ou incômodo'],['current','Estou com dor atualmente'],['return','Estou retornando de lesão']].map(([v,t])=>`<option value="${v}" ${p.pain===v?'selected':''}>${t}</option>`).join('')}</select></label></div><fieldset class="profile-days"><legend>Dias disponíveis para correr (2 a 6)</legend>${labels.map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${p.days?.includes(i)?'checked':''}> ${d}</label>`).join('')}</fieldset><label class="profile-consent"><input type="checkbox" name="consent" ${p.consent?'checked':''} required><span>Autorizo enviar objetivo, datas, volume, disponibilidade e situação de dores ao Google Gemini para gerar a sugestão. Meu e-mail não será enviado ao Gemini. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Termos do serviço</a>.</span></label><div class="notice">Você receberá as fases até o objetivo e os primeiros 28 dias detalhados, ou menos se a preparação for menor. A IA pode errar: revise a proposta, ajuste pela recuperação e procure orientação profissional quando necessário.</div><button type="submit" class="primary" ${busy||!account?'disabled':''}>${busy&&!checking?'Preparando sugestão…':'Gerar sugestão com Gemini'}</button><button type="button" class="secondary profile-check" data-profile="check" ${busy||!account?'disabled':''}>${checking?'Verificando conexão…':'Verificar conexão com Gemini'}</button><p id="profile-generation-status" class="notice profile-generation-feedback" role="status" aria-live="polite" ${status&&account?'':'hidden'}>${esc(status)}</p>${!account?'<p class="field-help">Entre na sua conta para gerar. O formulário pode ser preenchido antes.</p>':''}</form></section>${result?renderResult(result):''}`;}
function renderResult(r){return `<section id="profile-result" class="panel profile-result" tabindex="-1"><span class="eyebrow muted">SUGESTÃO DO GEMINI · REVISE ANTES DE TREINAR</span><h2>Uma preparação para você.</h2><p>${esc(r.plan.summary)}</p><div class="notice"><strong>Avaliação da meta</strong><p>${esc(r.plan.feasibility)}</p></div>${r.plan.warnings.length?`<ul>${r.plan.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<h3>As fases até o objetivo</h3><div class="profile-phases">${r.plan.phases.map(p=>`<article><span class="eyebrow muted">${esc(p.start)} → ${esc(p.end)}</span><h3>${esc(p.title)}</h3><p>${esc(p.focus)}</p></article>`).join('')}</div><h3>Primeiras semanas detalhadas</h3>${r.plan.weeks.map((w,i)=>`<details class="profile-week" ${i===0?'open':''}><summary>Semana ${i+1} · ${esc(w.start)} · ${w.totalKm.toLocaleString('pt-BR')} km</summary><p>${esc(w.focus)}</p>${w.sessions.map(s=>`<article class="profile-session"><strong>${esc(s.date)} · ${esc(s.title)}</strong><p>${s.km.toLocaleString('pt-BR')} km · ${s.minutes} min · RPE ${s.rpe}/10${s.long?' · Longo':''}</p><p>${esc(s.instructions)}</p></article>`).join('')||'<p>Recuperação e descanso.</p>'}</details>`).join('')}<p class="field-help">Reavalie por volta de ${esc(r.plan.reviewDate)} com os treinos efetivamente realizados. Modelo: ${esc(r.model)}. Gerado em ${esc(new Date(r.generatedAt).toLocaleString('pt-BR'))}.</p><div class="profile-buttons"><button class="primary" data-profile="adopt">Usar este plano</button><button class="secondary" data-profile="save">Salvar sugestão neste aparelho</button><button class="secondary" data-profile="export">Baixar sugestão (JSON)</button></div><p class="field-help">“Usar este plano” atualiza Plano, Hoje e as sessões para registro neste aparelho. “Salvar sugestão” guarda apenas esta proposta. Seu histórico anterior é preservado. Novas sugestões só entram no calendário quando você escolher usá-las.</p></section>`;}
function readForm(){const form=document.querySelector('#profile-goal');if(!form)return draft;const f=new FormData(form);return {goal:f.get('goal'),target:Number(f.get('target')),startDate:f.get('startDate'),targetDate:f.get('targetDate'),weeklyKm:Number(f.get('weeklyKm')),longestKm:Number(f.get('longestKm')),weeksConsistent:Number(f.get('weeksConsistent')),maxMinutes:Number(f.get('maxMinutes')),longMinutes:Number(f.get('longMinutes')),pain:f.get('pain'),days:f.getAll('days').map(Number),consent:f.get('consent')==='on'};}
function rememberDraft(){draft=readForm();}
function revealFeedback(resultReady=false){requestAnimationFrame(()=>{const node=document.querySelector(resultReady?'#profile-result':account?'#profile-generation-status':'#profile-status');node?.scrollIntoView?.({block:'nearest',behavior:'smooth'});if(resultReady)node?.focus?.({preventScroll:true});});}
document.addEventListener('invalid',e=>{if(!e.target.closest('#profile-goal'))return;status='Confira os campos obrigatórios e marque a autorização de envio ao Gemini.';const node=document.querySelector('#profile-generation-status');if(node){node.textContent=status;node.hidden=false;}},true);
document.addEventListener('input',e=>{if(e.target.closest('#profile-goal'))rememberDraft();});
document.addEventListener('change',e=>{if(e.target.closest('#profile-goal'))rememberDraft();});
document.addEventListener('submit',async e=>{
 if(!['profile-login','profile-goal'].includes(e.target.id))return;e.preventDefault();if(busy)return;
 let generated=false;const login=e.target.id==='profile-login',email=login?new FormData(e.target).get('email'):null;rememberDraft();let profile;
 if(!login){try{profile=validateProfile(draft);if(profile.pain!=='none')throw new Error('Com dor atual ou retorno de lesão, revise a preparação com um profissional antes de gerar cargas.');}catch(error){status=error.message;changed();revealFeedback();return;}}
 busy=true;status=login?'Solicitando seu link de acesso…':'O Gemini está preparando sua sugestão. Isso pode levar cerca de um minuto.';changed();if(!login)revealFeedback();
 try{if(login){const data=await api('auth/link',{email});status=data.message;}else{const data=await api('training/suggest',profile);result={...data,profile,plan:validateSuggestion(data.plan,profile)};generated=true;status='Sugestão pronta. Revise as fases e os treinos antes de salvar.';}}catch(error){status=error.message;}finally{busy=false;changed();if(!login)revealFeedback(generated);}
});
document.addEventListener('click',async e=>{const action=e.target.closest('[data-profile]')?.dataset.profile;if(!action||busy)return;
 if(action==='google'){rememberDraft();busy=true;status='Abrindo o acesso com Google…';changed();try{const data=await api('auth/google',{});location.assign(data.url);}catch(error){status=error.message;busy=false;changed();}}
 if(action==='adopt'&&result&&account){try{adoptSuggestion(account.id,result);status='Plano adotado neste aparelho. Abra a seção Plano para ver seus treinos.';window.dispatchEvent(new Event('active-plan-change'));location.hash='#plano';}catch(error){status=error.message;}changed();}
 if(action==='save'&&result&&account){try{localStorage.setItem(key(),JSON.stringify(result));status='Sugestão salva neste aparelho. Baixe um backup para ter outra cópia.';}catch{status='Não foi possível salvar. Baixe a sugestão para guardar uma cópia.';}changed();}
 if(action==='export'&&result){const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='dez-voltas-sugestao-'+result.profile.startDate+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 if(action==='check'){rememberDraft();busy=true;checking=true;status='Verificando chave e acesso ao modelo Gemini…';changed();revealFeedback();try{const data=await api('training/check',{});status=data.message;}catch(error){status=error.message;}finally{busy=false;checking=false;changed();revealFeedback();}}
 if(action==='logout'){busy=true;try{await api('auth/logout',{});account=null;setPlanOwner(null);window.dispatchEvent(new Event('active-plan-change'));result=null;draft=null;status='Você saiu da conta. As cópias salvas continuam neste aparelho.';}catch(error){status=error.message;}finally{busy=false;changed();}}
});
export async function initProfile(){try{const url=new URL(location.href),hash=new URLSearchParams(url.hash.slice(1)),code=url.searchParams.get('code'),error=url.searchParams.get('error_description')||hash.get('error_description'),errorCode=url.searchParams.get('error')||hash.get('error');if(code||url.searchParams.has('auth')||error||errorCode){history.replaceState(null,'','/#perfil');if(error||errorCode)throw new Error(errorCode==='access_denied'?'A entrada foi cancelada. Tente novamente ou use o link por e-mail.':'Não foi possível concluir o acesso. Tente entrar novamente.');if(!code)throw new Error('Link incompleto. Solicite outro e use o mesmo navegador.');const data=await api('auth/callback',{code});account=data.user;setPlanOwner(account.id);load();status='Acesso confirmado. Preencha seu objetivo para gerar uma sugestão.';}else{const data=await api('auth/me');account=data.user;setPlanOwner(account?.id||null);if(account)load();}}catch(error){status=error.message;}finally{authChecked=true;changed();window.dispatchEvent(new Event('active-plan-change'));}}
